using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;

namespace Truedat.Store
{
    /// <summary>
    /// Self-tests for store snapshot / restore / merge / state (store-v3 T09, T10, T12). Each test mints its own
    /// store, archive and catalog in a scratch directory and deletes it in <c>Dispose</c> — nothing is left behind
    /// and nothing outside the suite has to be regenerated by hand.
    ///
    /// What is pinned here: a snapshot taken with a store carries the store and its facts; restoring it puts the
    /// STORE back, snapshots the one it replaced, advances the generation and republishes the catalog from the
    /// restored store; a damaged or future store is refused BEFORE the live one is touched; a catalog-only archive
    /// is not a store snapshot; a merge source may be a store and is read across every root; and the state block
    /// names the right state and the command that closes it.
    /// </summary>
    internal static class StoreTransferSelfTest
    {
        internal static void Run(Action<bool, string> assert)
        {
            Console.WriteLine("Store-transfer self-test (T09: a snapshot carries the store; a restore puts the store back and republishes from it)");
            try { TestSnapshotAndRestore(assert); }
            catch (Exception ex) { assert(false, $"StoreTransfer.SnapshotRestore: threw {ex.GetType().Name}: {ex.Message}"); }

            Console.WriteLine("Store-transfer self-test (T09: a damaged store, a future schema and a catalog-only archive are refused before anything is replaced)");
            try { TestRestoreRefusals(assert); }
            catch (Exception ex) { assert(false, $"StoreTransfer.RestoreRefusals: threw {ex.GetType().Name}: {ex.Message}"); }

            Console.WriteLine("Store-transfer self-test (T10: a merge source may be a store, read across every root)");
            try { TestStoreAsMergeSource(assert); }
            catch (Exception ex) { assert(false, $"StoreTransfer.MergeSource: threw {ex.GetType().Name}: {ex.Message}"); }

            Console.WriteLine("Store-transfer self-test (T12: --store-info's state names the generation, the files' state and the next command)");
            try { TestStoreInfoState(assert); }
            catch (Exception ex) { assert(false, $"StoreTransfer.StoreInfoState: threw {ex.GetType().Name}: {ex.Message}"); }
        }

        sealed class Dir : IDisposable
        {
            internal readonly string Root;
            internal Dir() { Root = Path.Combine(Path.GetTempPath(), "truedat-transfer-selftest-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(Root); }
            internal string P(string name) => Path.Combine(Root, name);
            public void Dispose() { try { Directory.Delete(Root, true); } catch { } }
        }

        static TrackEntry E(string title, double bpm, char sha) => new TrackEntry
        {
            Features = new TrackFeatures { Artist = "A", Title = title, Bpm = bpm, Mfcc = new[] { 1.5, -2.25 } },
            LastModified = new DateTime(2026, 5, 1, 0, 0, 0, DateTimeKind.Utc), AudioStreamSha256 = new string(sha, 64),
        };

        static Dictionary<string, TrackEntry> Lib(string root, params (string Name, double Bpm, char Sha)[] items)
        {
            var d = new Dictionary<string, TrackEntry>(PathComparer.Instance);
            foreach (var (n, bpm, sha) in items) d[root + "\\" + n] = E(n, bpm, sha);
            return d;
        }

        static void Mint(string store, IReadOnlyDictionary<string, TrackEntry> entries, string root, string role = "primary")
        {
            using (StoreLog.Quiet())
                ImportCommand.ExecuteEntries(store, entries, root, role, true, "essentia", "x", "fixture", null, null);
        }

        /// <summary>A snapshot archive built the way <c>--snapshot</c> builds one with a store in force.</summary>
        static string Snapshot(Dir d, string store, string catalog, string name)
        {
            var staged = d.P(name + ".store.tmp");
            var copy = StoreTransfer.VacuumInto(store, staged);
            var member = new CatalogArchive.StoreMember(copy.Path, StoreTransfer.StoreEntryName, copy.Schema, copy.Generation, copy.Entries, copy.Sha256);
            var outPath = d.P(name);
            CatalogArchive.WriteSnapshot(catalog, null, outPath, "v-test", member);
            File.Delete(staged);
            return outPath;
        }

        static void TestSnapshotAndRestore(Action<bool, string> assert)
        {
            using (var d = new Dir())
            {
                var store = d.P("truedat.db");
                var catalog = d.P(Program.MoodsFileName);
                Mint(store, Lib(@"D:\music", ("a.flac", 120, 'a'), ("b.flac", 121, 'b')), @"D:\music");
                using (StoreLog.Quiet()) ExportCommand.Execute(new ExportOptions { StorePath = store, OutPath = catalog });
                long generationAtSnapshot = Collect(store).Generation;

                var archive = Snapshot(d, store, catalog, "snap.zip");
                assert(StoreTransfer.ArchiveContainsStore(archive), "snapshot: the archive carries the store");
                using (var zip = ZipFile.OpenRead(archive))
                {
                    var names = zip.Entries.Select(e => e.Name).ToList();
                    assert(names.Contains(StoreTransfer.StoreEntryName) && names.Contains(CatalogArchive.CatalogEntryName) && names.Contains(CatalogArchive.ManifestEntryName),
                        $"snapshot: catalog + manifest + {StoreTransfer.StoreEntryName} ({string.Join(", ", names)})");
                    using var ms = new MemoryStream();
                    using (var es = zip.GetEntry(CatalogArchive.ManifestEntryName)!.Open()) es.CopyTo(ms);
                    var man = System.Text.Json.Nodes.JsonNode.Parse(ms.ToArray())!;
                    assert((string?)man["storeEntry"] == StoreTransfer.StoreEntryName
                           && (long?)man["storeGeneration"] == generationAtSnapshot
                           && (long?)man["storeEntries"] == 2
                           && ((string?)man["storeSha256"])?.Length == 64
                           && (long?)man["storeSchema"] == StoreSchema.CurrentVersion,
                        $"snapshot: the manifest records the store's entry, schema, generation ({man["storeGeneration"]} vs {generationAtSnapshot}), locations and sha256");
                }

                // Move the live store on from the snapshot: a third entry, committed.
                Mint(store, Lib(@"D:\music", ("c.flac", 122, 'c')), @"D:\music");
                var infoBefore = Collect(store);
                assert(infoBefore.Counts["track_location"] == 3 && infoBefore.Generation > generationAtSnapshot,
                    $"setup: the live store moved on ({infoBefore.Counts["track_location"]} locations, generation {infoBefore.Generation} > {generationAtSnapshot})");

                int exit;
                using (StoreLog.Quiet()) exit = Program.RunStoreRestore(archive, store, catalog);
                assert(exit == 0, $"restore: exit 0 ({exit})");

                var after = Collect(store);
                assert(after.Counts["track_location"] == 2, $"restore: the store is the snapshot's again, 2 locations ({after.Counts["track_location"]})");
                assert(after.Generation > infoBefore.Generation,
                    $"restore: the generation ADVANCES past the live store's — a restore is a change the consumer must see even though the bytes are older ({after.Generation} > {infoBefore.Generation})");
                var backups = Directory.GetFiles(d.Root, Path.GetFileName(store) + ".bak.*");
                assert(backups.Length == 1, $"restore: the store it replaced was snapshotted first ({backups.Length} backup(s))");
                assert(StoreTransfer.Validate(backups[0]).Entries == 3, "restore: that backup is the 3-location store, consistent and readable");
                assert(!File.Exists(store + ".restore.tmp"), "restore: no staging file left behind");

                // The files are republished FROM the restored store, at its new generation.
                var republished = new System.Collections.Concurrent.ConcurrentDictionary<string, TrackEntry>(PathComparer.Instance);
                Program.LoadExistingMoodsForStore(catalog, republished);
                assert(republished.Count == 2 && !republished.ContainsKey(@"D:\music\c.flac"),
                    $"restore: the catalog was republished from the restored store, so the rolled-back entry is gone ({republished.Count})");
                assert(CatalogOrigin.TryRead(catalog, out var origin) && origin.Generation == after.Generation && origin.Kind.Length > 0,
                    $"restore: the republished catalog's origin carries the committed generation ({origin.Generation} vs {after.Generation})");
                assert(File.Exists(Path.ChangeExtension(catalog, ".mbxs")), "restore: the sidecar was published with it");
                assert(StoreResult.TryRead(StoreResult.PathFor(store), out var rec) && rec.Verb == "restore" && rec.Outcome == StoreResult.OutcomeCompleted
                       && rec.Store.Generation == after.Generation && rec.Export.Performed,
                    "restore: store-result.json names the verb, the committed generation and the publication");
            }
        }

        static void TestRestoreRefusals(Action<bool, string> assert)
        {
            // A damaged store inside the archive: refused, and the live store is untouched.
            using (var d = new Dir())
            {
                var store = d.P("truedat.db");
                var catalog = d.P(Program.MoodsFileName);
                Mint(store, Lib(@"D:\music", ("a.flac", 120, 'a')), @"D:\music");
                using (StoreLog.Quiet()) ExportCommand.Execute(new ExportOptions { StorePath = store, OutPath = catalog });
                var liveSha = StoreTransfer.Sha256File(store);

                var bad = d.P("bad.zip");
                using (var zfs = new FileStream(bad, FileMode.Create, FileAccess.Write, FileShare.None))
                using (var zip = new ZipArchive(zfs, ZipArchiveMode.Create))
                {
                    using (var es = zip.CreateEntry(CatalogArchive.CatalogEntryName).Open())
                        es.Write(new byte[] { (byte)'{', (byte)'}' }, 0, 2);
                    using (var es = zip.CreateEntry(StoreTransfer.StoreEntryName).Open())
                    {
                        var junk = System.Text.Encoding.ASCII.GetBytes("this is not a database");
                        es.Write(junk, 0, junk.Length);
                    }
                }
                assert(StoreTransfer.ArchiveContainsStore(bad), "setup: the bad archive does carry a file named like a store");
                int exit;
                using (StoreLog.Quiet()) exit = Program.RunStoreRestore(bad, store, catalog);
                assert(exit == 1, $"damaged store: refused with exit 1 ({exit})");
                assert(StoreTransfer.Sha256File(store) == liveSha, "damaged store: the live store is byte-identical — nothing was replaced");
                assert(Directory.GetFiles(d.Root, Path.GetFileName(store) + ".bak.*").Length == 0, "damaged store: no backup was churned");
                assert(!File.Exists(store + ".restore.tmp"), "damaged store: no staging file left behind");
                assert(StoreResult.TryRead(StoreResult.PathFor(store), out var rec) && rec.Outcome == StoreResult.OutcomeFailed && rec.Reason != null,
                    "damaged store: the record says failed and names the reason");
            }
            // A store from a newer schema: refused by the validator, with the reason an operator can act on.
            using (var d = new Dir())
            {
                var future = d.P("future.db");
                Mint(future, Lib(@"D:\music", ("a.flac", 120, 'a')), @"D:\music");
                using (var db = SqliteDb.Open(future, create: false))
                    db.Exec($"INSERT INTO schema_version (version, applied_utc, truedat_version) VALUES ({StoreSchema.CurrentVersion + 1}, '2030-01-01T00:00:00.0000000Z', 'v-future');");
                string? why = null;
                try { StoreTransfer.Validate(future); }
                catch (StoreException ex) { why = ex.Message; }
                assert(why != null && why.Contains($"v{StoreSchema.CurrentVersion + 1}") && why.Contains("nothing was replaced"),
                    $"future schema: refused naming the schema and that nothing was replaced ({why})");
            }
            // A catalog-only snapshot is not a store snapshot.
            using (var d = new Dir())
            {
                var catalog = d.P(Program.MoodsFileName);
                StoreSelfTest.WriteCatalog(catalog, Lib(@"D:\music", ("a.flac", 120, 'a')));
                var plain = d.P("catalog-only.zip");
                CatalogArchive.WriteSnapshot(catalog, null, plain, "v-test");
                assert(!StoreTransfer.ArchiveContainsStore(plain), "catalog-only snapshot: carries no store, so it cannot restore one");
            }
        }

        static void TestStoreAsMergeSource(Action<bool, string> assert)
        {
            using (var d = new Dir())
            {
                var store = d.P("truedat.db");
                var catalog = d.P(Program.MoodsFileName);
                Mint(store, Lib(@"D:\music", ("a.flac", 120, 'a'), ("b.flac", 121, 'b')), @"D:\music");
                // A second root, as a shard store minted on another machine has: its entries must come back too.
                Mint(store, Lib(@"X:\shard", ("c.flac", 122, 'c')), @"X:\shard", "mirror");
                using (StoreLog.Quiet()) ExportCommand.Execute(new ExportOptions { StorePath = store, OutPath = catalog, ExportRoot = @"D:\music" });

                assert(StoreTransfer.LooksLikeStore(store), "merge source: a store is recognised by SQLite's own header");
                assert(!StoreTransfer.LooksLikeStore(catalog), "merge source: a catalog is not mistaken for a store");

                var fromStore = StoreTransfer.ReadEntries(store);
                assert(fromStore.Count == 3 && fromStore.ContainsKey(@"D:\music\a.flac") && fromStore.ContainsKey(@"X:\shard\c.flac"),
                    $"merge source: every root is read — the shard's share is not dropped ({fromStore.Count}: {string.Join(", ", fromStore.Keys)})");

                // The store source renders through the catalog writer, so it merges byte-identically with a catalog source.
                var viaStore = ExportCommand.EntryJson(@"D:\music\a.flac", fromStore[@"D:\music\a.flac"]);
                var fromCatalog = new System.Collections.Concurrent.ConcurrentDictionary<string, TrackEntry>(PathComparer.Instance);
                Program.LoadExistingMoodsForStore(catalog, fromCatalog);
                var viaCatalog = ExportCommand.EntryJson(@"D:\music\a.flac", fromCatalog[@"D:\music\a.flac"]);
                assert(viaStore == viaCatalog, "merge source: a store source and a catalog source render identical bytes");

                assert(!StoreTransfer.LooksLikeStore(d.P("nope.db")), "merge source: a missing file is not a store (no throw)");
            }
        }

        static StoreInfo Collect(string store)
        {
            using (StoreLog.Quiet()) return StoreInfoCommand.Collect(store);
        }

        static void TestStoreInfoState(Action<bool, string> assert)
        {
            using (var d = new Dir())
            {
                var store = d.P("truedat.db");
                var catalog = d.P(Program.MoodsFileName);
                Mint(store, Lib(@"D:\music", ("a.flac", 120, 'a'), ("b.flac", 121, 'b')), @"D:\music");

                var absent = Collect(store);
                assert(absent.FilesState == "absent" && absent.PublishedGeneration == null && absent.NextCommand.Contains("--store-export"),
                    $"state: no catalog beside the store -> absent, and the next command publishes one ({absent.FilesState}: {absent.NextCommand})");
                assert(absent.Generation > 0 && absent.CatalogPath == catalog, "state: the store's generation and the catalog it would publish are named");

                using (StoreLog.Quiet()) ExportCommand.Execute(new ExportOptions { StorePath = store, OutPath = catalog });
                var published = Collect(store);
                assert(published.FilesState == "at-generation" && published.PublishedGeneration == published.Generation && published.FilesWhy == null,
                    $"state: published -> at-generation, the catalog's generation equals the store's ({published.FilesState}, {published.PublishedGeneration} vs {published.Generation})");
                assert(!published.NextCommand.Contains("--store-export"), $"state: nothing to publish, so the next command is not an export ({published.NextCommand})");

                Mint(store, Lib(@"D:\music", ("c.flac", 122, 'c')), @"D:\music");
                var behind = Collect(store);
                assert(behind.FilesState == "behind" && behind.PublishedGeneration < behind.Generation && behind.FilesWhy != null && behind.NextCommand.Contains("--store-export"),
                    $"state: a committed change -> behind, with the predicate's reason and the command that republishes ({behind.FilesState}: {behind.FilesWhy})");

                // A v1 catalog (no origin header) cannot be compared by generation at all: its own state, not a guess.
                StoreSelfTest.WriteCatalog(catalog, Lib(@"D:\music", ("a.flac", 120, 'a')));
                var legacy = Collect(store);
                assert(legacy.FilesState == "legacy" && legacy.PublishedGeneration == null && legacy.NextCommand.Contains("--store-export"),
                    $"state: a catalog with no origin header -> legacy, never reported as at-generation ({legacy.FilesState})");

                assert(legacy.EdgeArrayTracks == 0, "state: no edge arrays captured in a store with no edge rows");
            }
        }
    }
}
